import { useContext } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate } from 'react-router-dom';
import './navbar.scss';

const Navbar = () => {
  const { currentUser, setCurrentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();

  const handleLogout = () => {
    sessionStorage.removeItem('token');
    sessionStorage.removeItem('user');
    setCurrentUser(null);
    navigate('/login');
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Navbar: No profile picture provided, using fallback');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Navbar: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Navbar: Profile picture URL:', url);
    return url;
  };

  return (
    <div className={`navbar ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <div className="left">
        <span className="logo" onClick={() => navigate('/')}>SocialMedia</span>
      </div>
      <div className="right">
        {currentUser ? (
          <>
            <img
              src={getProfilePictureUrl(currentUser.profilePicture)}
              alt="Profile"
              className="profile-pic"
              onError={(e) => {
                console.error('Navbar: Image load error:', e);
                e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
              }}
            />
            <span>{currentUser.name}</span>
            <button onClick={handleLogout}>Logout</button>
          </>
        ) : (
          <button onClick={() => navigate('/login')}>Login</button>
        )}
      </div>
    </div>
  );
};

export default Navbar;
